/**
 * Schedulable job that purges old FB_Integration_Log__c records.
 *
 * Retention rules:
 *  - Logs with Level__c != 'ERROR' (including blank) are deleted once older than 30 days.
 *  - Logs with Level__c = 'ERROR' are kept longer and only deleted once older than 180 days.
 *
 * The purge runs synchronously within the scheduled execution so that the
 * deletion is guaranteed to have completed by the time the job finishes
 * (important for predictable behaviour in tests and monitoring).
 */
public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        purge();
    }

    /**
     * Deletes all FB_Integration_Log__c records that are eligible for purge
     * according to the retention rules described above.
     */
    public static void purge() {
        String errorLevel = 'ERROR';
        DateTime generalCutoff = DateTime.now().addDays(-30);
        DateTime errorCutoff = DateTime.now().addDays(-180);

        List<FB_Integration_Log__c> toDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != :errorLevel AND CreatedDate < :generalCutoff)
               OR (Level__c = :errorLevel AND CreatedDate < :errorCutoff)
               OR (Level__c = null AND CreatedDate < :generalCutoff)
        ];

        if (!toDelete.isEmpty()) {
            Database.delete(toDelete, false);
        }
    }

    /**
     * Schedules this job to run every night at 02:00 under the name
     * "Log purge (nightly)" and returns the resulting CronTrigger Id.
     */
    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
