/**
 * Singleton holder for the parent Account records needed by the Contact before-insert
 * trigger actions. The inner Service class is itself a Trigger Action (registered with the
 * lowest Order__c so it runs first) and is responsible for (re)loading accountsById on every
 * trigger execution, since later DML in the same transaction can touch other accounts.
 */
public inherited sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject so : triggerNew) {
                Contact c = (Contact) so;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            Map<Id, Account> freshAccountsById = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                freshAccountsById = new Map<Id, Account>(
                    [
                        SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                        FROM Account
                        WHERE Id IN :accountIds
                    ]
                );
            }

            TA_Contact_Queries.getInstance().accountsById = freshAccountsById;
        }
    }
}
