/**
 * Before-insert Trigger Action: when a new Contact has an Account and all four mailing
 * address fields are blank, copy the parent Account's billing address into the Contact's
 * mailing address. Relies on TA_Contact_Queries.Service having already loaded the parent
 * Accounts earlier in the same before insert context.
 */
public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            if (c.AccountId == null) {
                continue;
            }

            Boolean hasNoMailingAddress =
                String.isBlank(c.MailingStreet) &&
                String.isBlank(c.MailingCity) &&
                String.isBlank(c.MailingPostalCode) &&
                String.isBlank(c.MailingCountry);

            if (!hasNoMailingAddress) {
                continue;
            }

            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }

            c.MailingStreet = acc.BillingStreet;
            c.MailingCity = acc.BillingCity;
            c.MailingPostalCode = acc.BillingPostalCode;
            c.MailingCountry = acc.BillingCountry;
        }
    }
}
